WITH filtered_order_items AS (SELECT * FROM order_items WHERE product_id IS NULL), UnitPriceBucketSummary AS (SELECT CASE WHEN unit_price >= 340 THEN 'high' WHEN unit_price >= 80 THEN 'mid' ELSE 'low' END AS unit_price_bucket, MAX(quantity) AS max_quantity, COUNT(unit_price) AS unit_price_count FROM filtered_order_items GROUP BY CASE WHEN unit_price >= 340 THEN 'high' WHEN unit_price >= 80 THEN 'mid' ELSE 'low' END) SELECT unit_price_bucket, max_quantity, unit_price_count FROM UnitPriceBucketSummary ORDER BY 1 LIMIT 10;
